SELECT '1. 白名單已含 pricing_template_id（剛好 1 次）' AS 項目, (SELECT (length(replace(p.prosrc, E'\r', '')) - length(replace(replace(p.prosrc, E'\r', ''), '''package_id'',''pricing_template_id'',', ''))) / length('''package_id'',''pricing_template_id'',') = 1 FROM pg_proc p WHERE p.oid = to_regprocedure('public.update_order_fields_v1(uuid, jsonb, text, text)')) AS 結果
UNION ALL SELECT '2. 館別檢查剛好 1 處', (SELECT (length(replace(p.prosrc, E'\r', '')) - length(replace(replace(p.prosrc, E'\r', ''), 'PRICING_TEMPLATE_ACCOMMODATION_MISMATCH', ''))) / length('PRICING_TEMPLATE_ACCOMMODATION_MISMATCH') = 1 FROM pg_proc p WHERE p.oid = to_regprocedure('public.update_order_fields_v1(uuid, jsonb, text, text)'))
UNION ALL SELECT '3. 仍為 SECURITY INVOKER', (SELECT NOT p.prosecdef FROM pg_proc p WHERE p.oid = to_regprocedure('public.update_order_fields_v1(uuid, jsonb, text, text)'))
UNION ALL SELECT '4. authenticated 可執行、anon 不可', has_function_privilege('authenticated', to_regprocedure('public.update_order_fields_v1(uuid, jsonb, text, text)'), 'EXECUTE') AND NOT has_function_privilege('anon', to_regprocedure('public.update_order_fields_v1(uuid, jsonb, text, text)'), 'EXECUTE')
UNION ALL SELECT '5. 異動紀錄來源設定呼叫仍在（剛好 1 次）', (SELECT (length(replace(p.prosrc, E'\r', '')) - length(replace(replace(p.prosrc, E'\r', ''), 'PERFORM public.set_order_change_context(p_source, p_reason, NULL, ''user'');', ''))) / length('PERFORM public.set_order_change_context(p_source, p_reason, NULL, ''user'');') = 1 FROM pg_proc p WHERE p.oid = to_regprocedure('public.update_order_fields_v1(uuid, jsonb, text, text)'));

SELECT md5(replace(replace(replace(p.prosrc, E'\r', ''), E'  IF nullif(p_patch->>''pricing_template_id'', '''') IS NOT NULL AND NOT EXISTS (\n    SELECT 1 FROM public.pricing_templates t JOIN public.orders o ON o.accommodation_id = t.accommodation_id\n    WHERE o.id = p_order_id AND t.id = (p_patch->>''pricing_template_id'')::uuid\n  ) THEN\n    RAISE EXCEPTION ''PRICING_TEMPLATE_ACCOMMODATION_MISMATCH: 專案不屬於此訂單的館別 (%)'', p_patch->>''pricing_template_id'';\n  END IF;\n\n', ''), '''package_id'',''pricing_template_id'',', '''package_id'',')) AS 去掉兩處修改後的函式內容指紋,
       COALESCE(array_to_string(p.proacl, ','), '（預設）') AS 套用後權限, COALESCE(array_to_string(p.proconfig, ','), '（無）') AS 套用後設定, p.prosecdef AS 套用後_security_definer
FROM pg_proc p WHERE p.oid = to_regprocedure('public.update_order_fields_v1(uuid, jsonb, text, text)');
